import frappe
from frappe.utils import flt

def validate(doc, method=None):
    if flt(doc.loan_amount or 0) <= 0:
        frappe.throw("Loan amount must be greater than 0.")
    if not doc.loan_term_months or int(doc.loan_term_months) < 1:
        frappe.throw("Loan term must be at least 1 month.")
    if not doc.repayment_start_date:
        frappe.throw("Repayment start date is required.")
    if doc.repayment_start_date < doc.disbursement_date:
        frappe.throw("Repayment start date cannot be earlier than disbursement date.")
    missing=[]
    if not doc.disbursement_account:
        missing.append("Disbursement Account")
    if not doc.loan_account:
        missing.append("Loan Account")
    if not doc.interest_income_account:
        missing.append("Interest Income Account")
    if not doc.payment_account:
        missing.append("Payment Account")
    if missing:
        frappe.throw("Please set the following accounting fields before submitting: %s" % ", ".join(missing))
    if doc.applicant and not doc.applicant_name:
        try:
            linked = frappe.get_doc(doc.applicant_type, doc.applicant)
            doc.applicant_name = getattr(linked, "title") or getattr(linked, "customer_name") or getattr(linked, "bank") or linked.name
        except Exception:
            doc.applicant_name = doc.applicant

validate(doc)
